const s={ui:{fig:"Рис. 1",title:"Дно со складкой внутрь",svgLabel:"Изометрический рисунок того, как делается дно со складкой внутрь: сгиб посередине, две складки, прострочённые в 6 см от него, дно, заправленное внутрь, боковые швы через него и вывернутая сумка.",prev:"Предыдущий шаг",dot:(t,e)=>t?`Шаг ${t}: ${e}`:e,start:"Шаги →",next:"Дальше →",overview:"Обзор",stepOf:(t,e)=>`Шаг ${t} из ${e}`,machine:t=>`Машина: ${t.toLowerCase()}`,inThisStep:"В этом шаге",takeApart:"Поставить",putTogether:"Показать дно",replay:"↻ Повторить",parts:"Детали",allSteps:"Пошаговая инструкция",endView:"ВИД С ТОРЦА"},stitches:{straight:"Прямая строчка"},labels:{foldPress:"сложить пополам, заутюжить",centreCrease:"середина (сгиб)",cm6:"6 см",rightSides:"лицом к лицу",stitchFold:"строчка у самого сгиба",bottom12:"дно 12 см",liftEnds:"поднять концы на строчках",foldsIn:"дно складывается внутрь",centreInside:"середина — 6 см внутрь",seam05:"шов 0,5 см",layers4:"здесь 4 слоя",turnOut:"вывернуть на лицо",openUp:"расправить",base12:"дно 12 см",cornersForm:"уголки получаются сами"},steps:[{title:"Дно со складкой внутрь",text:"Дно шоппера, сумка перевёрнута: ровное основание 12 см между двумя прострочёнными складками и уголки, которые получаются сами, — без отдельных швов на уголках. Нажмите на сумку, чтобы поставить её."},{title:"Сгиб посередине и разметка",text:"Сложите деталь пополам поперёк, заутюжьте сгиб и разверните. Отмерьте от сгиба по 6 см к каждому концу и проведите поперёк линии.",details:["Сумка кроится одной деталью, которая складывается пополам поперёк: дно — посередине детали.","Сложите её пополам поперёк и заутюжьте сгиб. Снова разверните: сгиб — это середина дна.","Отмерьте от сгиба по 6 см к каждому концу и проведите исчезающим маркером линии по всей ширине детали."]},{title:"Прострочить складку на каждой линии",text:"Сложите по первой линии лицом к лицу и прострочите у самого сгиба. Разверните и сделайте то же по второй линии: две прострочённые складки на расстоянии 12 см.",details:["Сложите деталь по первой линии лицом к лицу и прострочите у самого сгиба по всей ширине. Разверните.","Так же сложите и прострочите по второй линии.","Две прострочённые складки на расстоянии 12 см друг от друга — это края дна, а центральный сгиб — его середина. В следующем шаге деталь сгибается по этим складкам."]},{title:"Заправить дно внутрь",text:"Поднимите оба конца на прострочённых складках и сведите их вместе: дно складывается внутрь, а центральный сгиб уходит на 6 см внутрь. Разложите деталь ровно.",details:["Положите деталь лицевой стороной вверх и поднимите оба конца, чтобы она согнулась по двум прострочённым складкам.","Сведите концы вместе. Дно шириной 12 см складывается внутрь, а центральный сгиб уходит между слоями на 6 см вверх — как дно бумажного пакета.","Разложите ровно, лицом к лицу. Теперь прострочённые складки — нижний край."]},{title:"Стачать бока",text:"Не расправляя дно, стачайте оба бока швом 0,5 см — через все слои, внизу их четыре.",details:["Закрепите бока зажимами, чтобы заправленное дно не сдвинулось.","Стачайте оба боковых шва в 0,5 см от края, до самого низа. Внизу шов проходит через четыре слоя: перед, две половинки заправленного дна и спинку. Верх оставьте открытым.","У шоппера подкладка сшивается так же — только в одном её боковом шве оставляют отверстие, чтобы потом вывернуть через него сумку."]},{title:"Вывернуть",text:"Выверните на лицевую сторону и расправьте: дно раскрывается в плоское основание 12 см, а уголки получаются сами.",details:["Выверните сумку на лицевую сторону через верх.","Расправьте сумку и вытолкните дно наружу. Заправленное дно раскрывается в плоское основание шириной 12 см, а там, где его захватили боковые швы, сами собой получаются аккуратные уголки — отдельно прострачивать их не нужно."]}],legend:[{title:"Основание",text:"плоское, шириной 12 см: дно между двумя прострочёнными складками"},{title:"Прострочённые складки",text:"складка, прострочённая у самого края, в 6 см по обе стороны от центрального сгиба · длинные края основания"},{title:"Центральный сгиб",text:"середина дна · заправляется на 6 см внутрь, прежде чем стачиваются боковые швы"},{title:"Боковые швы",text:"0,5 см, стачиваются вместе с заправленным дном · внизу четыре слоя"},{title:"Уголки",text:"получаются сами там, где боковые швы захватили заправленное дно · без швов на уголках"}]};export{s as default};
